INSERT INTO especies (slug, nombre_comun, otros_nombres, nombre_cientifico, familia, origen, distribucion, descripcion, dato_curioso, beneficios, altura_max_m, follaje, floracion_meses, color_flor, sprite, gbif_id, wikipedia_url, foto_url, foto_credito, fuente, follaje_texto, clima, floracion_texto) VALUES
  ('jacaranda', 'Jacaranda', ARRAY['Jacarandá', 'Tarco']::text[], 'Jacaranda mimosifolia', 'Bignoniaceae', 'introducida', 'Sudamérica (Argentina y Bolivia).', 'Árbol de copa amplia y follaje fino parecido al de un helecho. A finales del invierno se cubre de racimos de flores violeta en forma de campana.', 'Se popularizó en México a inicios del siglo XX; hoy su floración anuncia la primavera en las avenidas de Guadalajara.', ARRAY['Sombra ligera', 'Alimento para abejas y colibríes', 'Reduce la temperatura del entorno']::text[], 15, 'semicaducifolio', ARRAY[2, 3, 4]::int[], '#8E6CC4', '{"copa":"paraguas","hojas":["#3F6B3B","#5E8F4B","#8DB766"],"tronco":"#6B5444","flor":"#8E6CC4","densidadFlor":0.95,"alto":1,"ancho":1.1}'::jsonb, NULL, NULL, NULL, NULL, 'Catálogo curado Bosque CUCEI', 'Caducifolio', 'Tropical, subtropical, cálido', 'Flores en racimos de color morado o azul; fruto en cápsula'),
  ('primavera', 'Primavera', ARRAY['Palo blanco', 'Árbol de oro']::text[], 'Roseodendron donnell-smithii', 'Bignoniaceae', 'nativa', 'Vertiente del Pacífico de México y Centroamérica.', 'Árbol alto de tronco claro y recto. Tira sus hojas en la temporada seca y después se cubre por completo de flores amarillo dorado.', 'Durante su floración la copa no tiene hojas: todo el color que ves son flores.', ARRAY['Alimento para polinizadores', 'Madera apreciada', 'Captura de carbono']::text[], 25, 'caducifolio', ARRAY[2, 3, 4]::int[], '#EDBB1F', '{"copa":"abierta","hojas":["#466D3A","#679448","#97BE5E"],"tronco":"#B8A58C","flor":"#EDBB1F","densidadFlor":1,"alto":1.2,"ancho":0.95}'::jsonb, NULL, NULL, NULL, NULL, 'Catálogo curado Bosque CUCEI', NULL, NULL, NULL),
  ('rosa-morada', 'Rosa morada', ARRAY['Amapa', 'Macuilís', 'Maquilishuat', 'Apamate', 'Trompeta rosa']::text[], 'Tabebuia rosea', 'Bignoniaceae', 'nativa', 'Del sur de México hasta el norte de Sudamérica.', 'Árbol de hojas compuestas de cinco folíolos. En la temporada seca se llena de flores rosa lila en forma de trompeta.', 'Es el árbol nacional de El Salvador, donde se le llama maquilishuat.', ARRAY['Alimento para abejas y colibríes', 'Sombra amplia', 'Madera para muebles']::text[], 25, 'caducifolio', ARRAY[2, 3, 4]::int[], '#E58DBB', '{"copa":"redonda","hojas":["#3E6A3A","#5C8C49","#8AB463"],"tronco":"#7A6553","flor":"#E58DBB","densidadFlor":0.85,"alto":1.1,"ancho":1}'::jsonb, NULL, NULL, NULL, NULL, 'Catálogo curado Bosque CUCEI', 'Verde', 'Tropical', 'Flores rosadas, frutos en cápsulas'),
  ('tabachin', 'Tabachín', ARRAY['Flamboyán', 'Framboyán']::text[], 'Delonix regia', 'Fabaceae', 'introducida', 'Madagascar.', 'Árbol de copa muy extendida en forma de sombrilla y hojas finamente divididas. Al inicio de las lluvias se cubre de flores rojo anaranjado.', 'Sus vainas leñosas pueden medir más de medio metro y suenan como sonaja cuando se secan.', ARRAY['Sombra muy amplia', 'Alimento para polinizadores', 'Reduce la temperatura del entorno']::text[], 12, 'semicaducifolio', ARRAY[5, 6, 7]::int[], '#E4572E', '{"copa":"paraguas","hojas":["#3B6936","#5A8E45","#8BBA5E"],"tronco":"#6E5A48","flor":"#E4572E","densidadFlor":0.9,"alto":0.85,"ancho":1.35}'::jsonb, NULL, NULL, NULL, NULL, 'Catálogo curado Bosque CUCEI', 'Caduco', 'Tropical y subtropical', 'Flores rojas o anaranjadas llamativas; frutos en vainas largas y duras'),
  ('fresno', 'Fresno', ARRAY['Fresno de Uhde']::text[], 'Fraxinus uhdei', 'Oleaceae', 'nativa', 'México y Centroamérica, cerca de ríos y cañadas.', 'Árbol de crecimiento rápido con hojas compuestas y copa redondeada. Es de los más plantados en calles y parques de Guadalajara.', 'Sus semillas tienen un ala que las hace girar como hélice al caer.', ARRAY['Sombra densa', 'Captura de carbono', 'Refugio para aves']::text[], 25, 'semicaducifolio', '{}'::int[], NULL, '{"copa":"redonda","hojas":["#2F5E35","#4A8044","#78AA5A"],"tronco":"#7C6A58","alto":1.15,"ancho":1}'::jsonb, NULL, NULL, NULL, NULL, 'Catálogo curado Bosque CUCEI', 'Caduco o semi-persistente', 'Templado y subtropical', 'Flores pequeñas; frutos en sámaras aladas'),
  ('ficus-benjamina', 'Ficus', ARRAY['Laurel benjamina', 'Árbol de hule chico']::text[], 'Ficus benjamina', 'Moraceae', 'introducida', 'Sur y sureste de Asia y norte de Australia.', 'Árbol perenne de hojas brillantes y ramas colgantes. Muy usado en camellones y patios por su sombra constante.', 'Sus raíces son tan fuertes que pueden levantar banquetas y romper tuberías.', ARRAY['Sombra todo el año', 'Frutos para aves', 'Barrera contra el polvo']::text[], 20, 'perenne', '{}'::int[], NULL, '{"copa":"redonda","hojas":["#24502E","#3B7140","#5F9850"],"tronco":"#8A7B6A","alto":0.95,"ancho":1.15}'::jsonb, NULL, NULL, NULL, NULL, 'Catálogo curado Bosque CUCEI', 'Persistente', 'Tropical, subtropical, cálido-templado', 'Higos pequeños no comestibles'),
  ('laurel-de-la-india', 'Laurel de la India', ARRAY['Ficus de la India']::text[], 'Ficus microcarpa', 'Moraceae', 'introducida', 'Sur de Asia hasta Australia.', 'Árbol perenne de copa enorme y tronco grueso, común en plazas. Con los años desarrolla raíces aéreas que bajan de las ramas.', 'Sus higos diminutos solo pueden ser polinizados por una avispa específica.', ARRAY['Sombra muy amplia', 'Refugio para aves', 'Reduce la temperatura del entorno']::text[], 20, 'perenne', '{}'::int[], NULL, '{"copa":"redonda","hojas":["#1F4A2B","#356B3B","#56904B"],"tronco":"#93877A","alto":0.9,"ancho":1.4}'::jsonb, NULL, NULL, NULL, NULL, 'Catálogo curado Bosque CUCEI', 'Perennifolio', 'Tropical, subtropical, cálido', 'Flores pequeñas dentro del higo; fruto en higos comestibles para fauna'),
  ('eucalipto', 'Eucalipto', ARRAY['Eucalipto rojo']::text[], 'Eucalyptus camaldulensis', 'Myrtaceae', 'introducida', 'Australia.', 'Árbol muy alto de corteza lisa que se desprende en tiras. Sus hojas alargadas cuelgan de lado y desprenden un aroma característico.', 'Sus hojas giran de canto al sol para perder menos agua; por eso su sombra es ligera.', ARRAY['Rompevientos', 'Alimento para abejas', 'Crecimiento rápido']::text[], 40, 'perenne', '{}'::int[], NULL, '{"copa":"columnar","hojas":["#4C6B4E","#6B8C66","#9AB58E"],"tronco":"#D6CFC2","alto":1.35,"ancho":0.85}'::jsonb, NULL, NULL, NULL, NULL, 'Catálogo curado Bosque CUCEI', NULL, NULL, NULL),
  ('casuarina', 'Casuarina', ARRAY['Pino australiano']::text[], 'Casuarina equisetifolia', 'Casuarinaceae', 'introducida', 'Australia y sureste de Asia.', 'Árbol de silueta cónica que parece un pino, con ramillas verdes y delgadas que suenan con el viento.', 'Lo que parecen agujas son ramitas; sus hojas verdaderas son escamas diminutas.', ARRAY['Rompevientos', 'Fija nitrógeno en el suelo', 'Controla la erosión']::text[], 25, 'perenne', '{}'::int[], NULL, '{"copa":"conica","hojas":["#344F3A","#4D6B4F","#748F6E"],"tronco":"#6A5747","alto":1.25,"ancho":0.8}'::jsonb, NULL, NULL, NULL, NULL, 'Catálogo curado Bosque CUCEI', '"Hojas" reducidas transformadas en escamas finas de color verde, dispuestas en filamentos', 'Tropical y subtropical; ideal en zonas costeras y de clima cálido, aunque tolera cierta aridez', 'Produce flores diminutas e inconspicuas en amentos; el fruto es una cápsula leñosa que se abre para liberar semillas aladas, facilitando su dispersión'),
  ('cedro-blanco', 'Cedro blanco', ARRAY['Ciprés mexicano', 'Ciprés de México']::text[], 'Cupressus lusitanica', 'Cupressaceae', 'nativa', 'Montañas de México y Centroamérica.', 'Conífera de copa cónica y follaje en escamas de color verde azulado. Se usa mucho como cortina rompevientos.', 'Su nombre dice «lusitanica» (de Portugal) porque fue descrito a partir de árboles plantados allá, pero es originario de México.', ARRAY['Rompevientos', 'Refugio para aves', 'Captura de carbono']::text[], 25, 'perenne', '{}'::int[], NULL, '{"copa":"conica","hojas":["#2A4D3E","#3F6A54","#64907A"],"tronco":"#6B4F3A","alto":1.2,"ancho":0.9}'::jsonb, NULL, NULL, NULL, NULL, 'Catálogo curado Bosque CUCEI', 'Hojas en forma de escamas, densas y de color verde oscuro, que pueden adquirir tonalidades grisáceas con la edad', 'Cálido y seco; se adapta también a climas templados', 'Flores diminutas y poco vistosas en racimos; fruto en cápsula que al madurar libera pequeñas semillas'),
  ('ahuehuete', 'Ahuehuete', ARRAY['Sabino', 'Ciprés de Moctezuma']::text[], 'Taxodium mucronatum', 'Cupressaceae', 'nativa', 'México, a la orilla de ríos y manantiales.', 'Conífera longeva de tronco muy grueso y ramillas colgantes. Necesita suelos húmedos y puede vivir más de mil años.', 'Es el árbol nacional de México; el Árbol del Tule, en Oaxaca, es un ahuehuete.', ARRAY['Longevidad excepcional', 'Protege riberas', 'Refugio para aves']::text[], 40, 'semicaducifolio', '{}'::int[], NULL, '{"copa":"columnar","hojas":["#2E5A3A","#47784E","#6E9E68"],"tronco":"#7A5A40","alto":1.25,"ancho":1.1}'::jsonb, NULL, NULL, NULL, NULL, 'Catálogo curado Bosque CUCEI', 'Hojas en forma de escamas o aguja, de color verde oscuro, de carácter perenne', 'Tropical a subtropical; prefiere ambientes cálidos y con disponibilidad de agua', 'Produce pequeños conos; la floración es poco vistosa y los frutos (conos) maduran a tonos marrones'),
  ('pirul', 'Pirul', ARRAY['Pirú', 'Árbol del Perú', 'Falso pimentero']::text[], 'Schinus molle', 'Anacardiaceae', 'introducida', 'Andes de Sudamérica.', 'Árbol de ramas colgantes y hojas aromáticas. Produce racimos de frutos pequeños color rosa.', 'Llegó a México en el siglo XVI; sus frutos se venden como «pimienta rosa».', ARRAY['Resiste la sequía', 'Frutos para aves', 'Sombra ligera']::text[], 15, 'perenne', '{}'::int[], '#E07A8F', '{"copa":"llorona","hojas":["#4A6B3E","#6A8D52","#98B677"],"tronco":"#6F5848","flor":"#E07A8F","densidadFlor":0.5,"alto":0.95,"ancho":1.15}'::jsonb, NULL, NULL, NULL, NULL, 'Catálogo curado Bosque CUCEI', 'Persistente', 'Cálido, templado, resistente a sequías', 'Flores pequeñas y blancas; frutos en racimos rosados'),
  ('mezquite', 'Mezquite', ARRAY['Mezquite dulce']::text[], 'Prosopis laevigata', 'Fabaceae', 'nativa', 'Centro y norte de México.', 'Árbol espinoso de tronco torcido y copa abierta, adaptado a climas secos. Florece en espigas color crema.', 'Con sus vainas dulces se preparaba harina y pinole desde tiempos prehispánicos.', ARRAY['Fija nitrógeno en el suelo', 'Resiste la sequía', 'Vainas comestibles']::text[], 10, 'caducifolio', ARRAY[3, 4, 5]::int[], '#E8D27C', '{"copa":"paraguas","hojas":["#4F6D3A","#6F8F4D","#9DB46F"],"tronco":"#5C4636","flor":"#E8D27C","densidadFlor":0.45,"alto":0.8,"ancho":1.2}'::jsonb, NULL, NULL, NULL, NULL, 'Catálogo curado Bosque CUCEI', NULL, NULL, NULL),
  ('huizache', 'Huizache', ARRAY['Acacia aromática', 'Vinorama']::text[], 'Vachellia farnesiana', 'Fabaceae', 'nativa', 'Regiones cálidas de América.', 'Árbol pequeño y espinoso de hojas finas. En invierno se llena de bolitas amarillas muy perfumadas.', 'Sus flores se usan en perfumería francesa con el nombre de «cassie».', ARRAY['Fija nitrógeno en el suelo', 'Alimento para abejas', 'Resiste la sequía']::text[], 8, 'semicaducifolio', ARRAY[12, 1, 2, 3]::int[], '#F5C518', '{"copa":"paraguas","hojas":["#4B6A38","#6A8A4A","#97B26A"],"tronco":"#5B4535","flor":"#F5C518","densidadFlor":0.7,"alto":0.7,"ancho":1.1}'::jsonb, NULL, NULL, NULL, NULL, 'Catálogo curado Bosque CUCEI', NULL, NULL, NULL),
  ('colorin', 'Colorín', ARRAY['Pichoco', 'Zompantle']::text[], 'Erythrina coralloides', 'Fabaceae', 'nativa', 'Centro y sur de México.', 'Árbol de ramas gruesas con pequeñas espinas. Antes de echar hojas se cubre de flores rojas alargadas.', 'Sus semillas rojas son tóxicas, pero sus flores cocidas («gasparitos») se comen en el centro del país.', ARRAY['Alimento para colibríes', 'Fija nitrógeno en el suelo', 'Cercas vivas']::text[], 10, 'caducifolio', ARRAY[1, 2, 3]::int[], '#D7263D', '{"copa":"abierta","hojas":["#43683A","#62904C","#90B868"],"tronco":"#8C7A68","flor":"#D7263D","densidadFlor":0.85,"alto":0.9,"ancho":1}'::jsonb, NULL, NULL, NULL, NULL, 'Catálogo curado Bosque CUCEI', NULL, NULL, NULL),
  ('tulipan-africano', 'Tulipán africano', ARRAY['Galeana', 'Llama del bosque']::text[], 'Spathodea campanulata', 'Bignoniaceae', 'introducida', 'África tropical.', 'Árbol de hojas grandes y brillantes que da racimos de flores rojo anaranjado en forma de copa durante buena parte del año.', 'Sus botones guardan agua; en muchos países los niños los usan como pistolas de agua.', ARRAY['Floración larga', 'Alimento para aves', 'Sombra densa']::text[], 20, 'perenne', ARRAY[11, 12, 1, 2, 3, 4]::int[], '#F05D23', '{"copa":"redonda","hojas":["#2C5A32","#447A42","#6CA05A"],"tronco":"#7E6B58","flor":"#F05D23","densidadFlor":0.6,"alto":1.1,"ancho":1}'::jsonb, NULL, NULL, NULL, NULL, 'Catálogo curado Bosque CUCEI', 'Verde', 'Tropical', 'Flores rojas-anaranjadas, frutos en cápsulas'),
  ('grevilea', 'Grevilea', ARRAY['Roble australiano', 'Roble plateado']::text[], 'Grevillea robusta', 'Proteaceae', 'introducida', 'Este de Australia.', 'Árbol alto y esbelto de hojas parecidas a las de un helecho, plateadas por debajo. En primavera da flores anaranjadas en forma de cepillo.', 'Pese a llamarse «roble australiano», no es pariente de los robles.', ARRAY['Alimento para aves y abejas', 'Rompevientos', 'Crecimiento rápido']::text[], 30, 'perenne', ARRAY[3, 4, 5]::int[], '#F2A541', '{"copa":"columnar","hojas":["#3E5F3E","#5F805A","#93AE86"],"tronco":"#5E4A3C","flor":"#F2A541","densidadFlor":0.55,"alto":1.3,"ancho":0.85}'::jsonb, NULL, NULL, NULL, NULL, 'Catálogo curado Bosque CUCEI', 'Verde', 'Subtropical', 'Flores anaranjadas, frutos leñosos'),
  ('palma-washingtonia', 'Palma washingtonia', ARRAY['Palma de abanico', 'Palma colorada', 'Palmera de abanico mexicana']::text[], 'Washingtonia robusta', 'Arecaceae', 'nativa', 'Baja California Sur y Sonora, México.', 'Palma muy alta y delgada con hojas en forma de abanico. Las hojas secas quedan colgando y forman una falda alrededor del tronco.', 'No es un árbol en sentido estricto: su tronco no forma madera ni anillos de crecimiento.', ARRAY['Refugio para aves y murciélagos', 'Resiste la sequía', 'Referencia visual del paisaje']::text[], 25, 'perenne', '{}'::int[], NULL, '{"copa":"palmera","hojas":["#35643B","#52864A","#82AE63"],"tronco":"#9C8468","alto":1.4,"ancho":0.9}'::jsonb, NULL, NULL, NULL, NULL, 'Catálogo curado Bosque CUCEI', 'Verde', 'Tropical', 'Flores blancas, frutos negros'),
  ('guamuchil', 'Guamúchil', ARRAY['Pinzán', 'Guamúchil dulce']::text[], 'Pithecellobium dulce', 'Fabaceae', 'nativa', 'De México a Sudamérica.', 'Árbol espinoso de copa redondeada. Sus vainas enroscadas se abren y muestran una pulpa blanca o rosada comestible.', 'En los mercados de Jalisco se venden sus vainas en temporada como golosina.', ARRAY['Frutos comestibles', 'Fija nitrógeno en el suelo', 'Resiste la sequía']::text[], 15, 'semicaducifolio', ARRAY[1, 2, 3]::int[], NULL, '{"copa":"redonda","hojas":["#3A6237","#568447","#84AE60"],"tronco":"#6E5B4B","flor":"#E9A3B6","densidadFlor":0.35,"alto":0.95,"ancho":1.1}'::jsonb, NULL, NULL, NULL, NULL, 'Catálogo curado Bosque CUCEI', 'Perennifolio', 'Cálido, subtropical, semiárido', 'Flores blancas y aromáticas; fruto en vaina curvada con pulpa dulce'),
  ('parota', 'Parota', ARRAY['Guanacaste', 'Orejón']::text[], 'Enterolobium cyclocarpum', 'Fabaceae', 'nativa', 'De México a Sudamérica, en zonas cálidas.', 'Árbol gigante de copa muy ancha y tronco robusto. Sus frutos son vainas enrolladas con forma de oreja.', 'Por la forma de sus frutos también se le llama «orejón»; es el árbol nacional de Costa Rica.', ARRAY['Sombra enorme', 'Fija nitrógeno en el suelo', 'Alimento para fauna']::text[], 30, 'caducifolio', '{}'::int[], NULL, '{"copa":"paraguas","hojas":["#355F34","#517F45","#7FAA5C"],"tronco":"#5F4B3B","alto":1,"ancho":1.45}'::jsonb, NULL, NULL, NULL, NULL, 'Catálogo curado Bosque CUCEI', 'Caducifolio', 'Cálido, tropical, subtropical', 'Flores blancas globosas; fruto en vaina dura y retorcida'),
  ('pochote', 'Pochote', ARRAY['Ceiba de hoja de castaño', 'Pochota']::text[], 'Ceiba aesculifolia', 'Malvaceae', 'nativa', 'Selvas secas de México y Centroamérica.', 'Árbol de tronco verdoso cubierto de espinas cónicas. En la temporada seca da flores grandes color crema.', 'Sus frutos guardan una fibra algodonosa con la que se rellenaban almohadas.', ARRAY['Alimento para murciélagos polinizadores', 'Resiste la sequía', 'Especie del bosque seco de Jalisco']::text[], 15, 'caducifolio', ARRAY[1, 2, 3]::int[], '#F1E4C3', '{"copa":"abierta","hojas":["#46693B","#658E4C","#94B76C"],"tronco":"#8E9A7A","flor":"#F1E4C3","densidadFlor":0.55,"alto":1,"ancho":1.05}'::jsonb, NULL, NULL, NULL, NULL, 'Catálogo curado Bosque CUCEI', NULL, NULL, NULL),
  ('trueno', 'Trueno', ARRAY['Aligustre', 'Ligustro']::text[], 'Ligustrum lucidum', 'Oleaceae', 'introducida', 'China.', 'Árbol perenne de hojas brillantes muy usado en banquetas. Da racimos de florecitas blancas y luego frutos negro azulado.', 'Se propaga tan fácil con ayuda de las aves que en algunos países se considera especie invasora.', ARRAY['Sombra todo el año', 'Frutos para aves', 'Tolera la contaminación']::text[], 12, 'perenne', ARRAY[4, 5, 6]::int[], '#F4F1E8', '{"copa":"redonda","hojas":["#264F32","#3C6E44","#629553"],"tronco":"#7B7062","flor":"#F4F1E8","densidadFlor":0.4,"alto":0.9,"ancho":1}'::jsonb, NULL, NULL, NULL, NULL, 'Catálogo curado Bosque CUCEI', NULL, NULL, NULL),
  ('sauce-lloron', 'Sauce llorón', ARRAY['Sauce de Babilonia']::text[], 'Salix babylonica', 'Salicaceae', 'introducida', 'Norte de China.', 'Árbol de ramas largas y colgantes que casi tocan el suelo. Prefiere lugares húmedos, cerca de fuentes o canales.', 'De la corteza de los sauces se obtuvo la salicina, antecesora de la aspirina.', ARRAY['Controla la erosión', 'Sombra fresca', 'Refugio para aves']::text[], 15, 'caducifolio', '{}'::int[], NULL, '{"copa":"llorona","hojas":["#4F7A3E","#73A055","#A5C978"],"tronco":"#6D5A48","alto":1,"ancho":1.2}'::jsonb, NULL, NULL, NULL, NULL, 'Catálogo curado Bosque CUCEI', 'Verde', 'Templado', 'Flores amarillas, frutos en cápsulas'),
  ('mango', 'Mango', ARRAY['Mango manila', 'Mango ataulfo']::text[], 'Mangifera indica', 'Anacardiaceae', 'introducida', 'Sur de Asia.', 'Árbol perenne de copa densa y hojas largas; los brotes nuevos salen rojizos. Sus frutos maduran al inicio del verano.', 'Llegó a México desde Filipinas con el Galeón de Manila.', ARRAY['Frutos comestibles', 'Sombra densa', 'Alimento para fauna']::text[], 25, 'perenne', ARRAY[1, 2, 3]::int[], '#F4A259', '{"copa":"redonda","hojas":["#1F4B2C","#336A3A","#5B9150"],"tronco":"#5E4B3D","flor":"#F4A259","densidadFlor":0.35,"alto":1,"ancho":1.15}'::jsonb, NULL, NULL, NULL, NULL, 'Catálogo curado Bosque CUCEI', 'Perenne', 'Tropical, subtropical', 'Flores pequeñas, amarillentas; frutos carnosos, dulces y de pulpa anaranjada'),
  ('guayabo', 'Guayabo', ARRAY['Guayaba']::text[], 'Psidium guajava', 'Myrtaceae', 'nativa', 'América tropical.', 'Árbol pequeño de tronco liso y manchado, con flores blancas de muchos estambres y frutos aromáticos.', 'Su corteza se descama en placas y deja el tronco pintado de verde, café y rojizo.', ARRAY['Frutos comestibles', 'Alimento para aves', 'Usos medicinales tradicionales']::text[], 8, 'perenne', ARRAY[3, 4, 5]::int[], '#FFF6DF', '{"copa":"abierta","hojas":["#3D6A3A","#5A8E4A","#89B766"],"tronco":"#A0785A","flor":"#FFF6DF","densidadFlor":0.4,"alto":0.7,"ancho":1}'::jsonb, NULL, NULL, NULL, NULL, 'Catálogo curado Bosque CUCEI', 'Perennifolio', 'Tropical, subtropical, cálido', 'Flores blancas aromáticas; fruto redondo, amarillo o rosado, comestible'),
  ('pata-de-vaca', 'Pata de vaca', ARRAY['Orquídea de pobre', 'Bauhinia']::text[], 'Bauhinia variegata', 'Fabaceae', 'introducida', 'Sur y sureste de Asia.', 'Árbol mediano de hojas partidas en dos lóbulos. Sus flores rosa lila recuerdan a una orquídea.', 'Sus hojas tienen forma de pezuña, de ahí su nombre.', ARRAY['Floración vistosa', 'Alimento para polinizadores', 'Tamaño ideal para banquetas']::text[], 10, 'semicaducifolio', ARRAY[1, 2, 3, 4]::int[], '#D98CB3', '{"copa":"redonda","hojas":["#4A7040","#6A9552","#9CBF77"],"tronco":"#76675A","flor":"#D98CB3","densidadFlor":0.75,"alto":0.85,"ancho":1}'::jsonb, NULL, NULL, NULL, NULL, 'Catálogo curado Bosque CUCEI', 'Hojas bilobuladas (forma de mariposa), de color verde brillante; pueden ser caducas o semi-perennes según el clima', 'Tropical y subtropical; tolera heladas leves', 'Flores grandes y vistosas, con forma orquídea, en tonos rosados, púrpura o blancos, que aparecen en primavera o verano; fruto en forma de vaina con semillas dispersas por el viento'),
  ('olmo-chino', 'Olmo chino', ARRAY['Olmo']::text[], 'Ulmus parvifolia', 'Ulmaceae', 'introducida', 'China, Corea y Japón.', 'Árbol de hojas pequeñas y aserradas, con ramas finas algo colgantes. Su corteza se desprende en placas de colores.', 'Es una de las especies favoritas para hacer bonsáis.', ARRAY['Sombra moderada', 'Tolera la contaminación', 'Resiste la sequía']::text[], 15, 'semicaducifolio', '{}'::int[], NULL, '{"copa":"redonda","hojas":["#3A6439","#58884A","#87B064"],"tronco":"#8A735E","alto":1,"ancho":1.05}'::jsonb, NULL, NULL, NULL, NULL, 'Catálogo curado Bosque CUCEI', 'Deciduo', 'Templado, subtropical', 'Flores pequeñas y discretas; fruto en samaras aladas'),
  ('crespon', 'Crespón', ARRAY['Astronómica', 'Árbol de Júpiter']::text[], 'Lagerstroemia indica', 'Lythraceae', 'introducida', 'China y sureste de Asia.', 'Árbol pequeño de tronco liso y jaspeado. En verano se cubre de racimos de flores rosas con pétalos arrugados.', 'Sus pétalos parecen papel crepé; por eso se le llama crespón.', ARRAY['Floración larga', 'Tamaño ideal para banquetas', 'Alimento para polinizadores']::text[], 7, 'caducifolio', ARRAY[6, 7, 8, 9]::int[], '#E26D9A', '{"copa":"abierta","hojas":["#42693C","#5F8F4C","#8DB86A"],"tronco":"#A98E78","flor":"#E26D9A","densidadFlor":0.85,"alto":0.7,"ancho":0.9}'::jsonb, NULL, NULL, NULL, NULL, 'Catálogo curado Bosque CUCEI', 'Hojas simples, alternas, de color verde oscuro que en otoño adquieren tonalidades rojizas o amarillentas', 'Tropical y subtropical; crece en zonas cálidas con inviernos suaves', 'Floración espectacular en verano: racimos de flores con tonalidades que varían entre rosa, púrpura, blanco o rojo; fruto en forma de cápsula con semillas aladas, de rápida germinación'),
  ('tronadora', 'Tronadora', ARRAY['Retama', 'Lluvia de oro']::text[], 'Tecoma stans', 'Bignoniaceae', 'nativa', 'Regiones cálidas de América, incluido el occidente de México.', 'Árbol pequeño o arbusto grande de hojas aserradas. Florece en racimos de campanas amarillas muy visitadas por colibríes.', 'Es la flor nacional de las Bahamas y de las Islas Vírgenes de Estados Unidos.', ARRAY['Alimento para colibríes y abejas', 'Resiste la sequía', 'Crecimiento rápido']::text[], 6, 'semicaducifolio', ARRAY[8, 9, 10, 11, 12]::int[], '#F7C531', '{"copa":"abierta","hojas":["#3F6A38","#5D9047","#8DBB63"],"tronco":"#6C5A49","flor":"#F7C531","densidadFlor":0.7,"alto":0.65,"ancho":0.95}'::jsonb, NULL, NULL, NULL, NULL, 'Catálogo curado Bosque CUCEI', NULL, NULL, NULL),
  ('ceiba', 'Ceiba', ARRAY['Caiba']::text[], 'Ceiba pentandra', 'Malvaceae', 'nativa', NULL, 'Ceiba (Ceiba pentandra) es una especie de la familia Malvaceae registrada en el inventario de árboles de CUCEI.', NULL, '{}'::text[], NULL, 'caducifolio', '{}'::int[], '#E58DBB', '{"copa":"abierta","hojas":["#3E6A3A","#5C8C49","#8AB463"],"tronco":"#76675A","flor":"#E58DBB","densidadFlor":0.45,"alto":1,"ancho":1}'::jsonb, NULL, NULL, NULL, NULL, 'Inventario de árboles de CUCEI', 'Hojas compuestas, perennes en clima tropical, que pueden ser caducifolias en zonas más frías', 'Tropical; tolera periodos de sequía moderada', 'Flores grandes, de tonos rosados o blancos, con aroma dulce; fruto en forma de cápsula leñosa que al madurar libera semillas recubiertas de fibra (kapok)'),
  ('nispero', 'Níspero', ARRAY['Níspero del Japón']::text[], 'Eriobotrya japonica', 'Rosaceae', 'introducida', NULL, 'Níspero (Eriobotrya japonica) es una especie de la familia Rosaceae registrada en el inventario de árboles de CUCEI.', NULL, '{}'::text[], NULL, 'perenne', '{}'::int[], '#F2994A', '{"copa":"redonda","hojas":["#3A6439","#58884A","#87B064"],"tronco":"#76675A","flor":"#F2994A","densidadFlor":0.85,"alto":1,"ancho":1}'::jsonb, NULL, NULL, NULL, NULL, 'Inventario de árboles de CUCEI', 'Perennifolio', 'Subtropical, templado', 'Flores blancas en racimos; fruto comestible, amarillo-naranja'),
