  ('filodendro', 'Filodendro', '{}'::text[], 'Philodendron spp.', 'Araceae', NULL, NULL, 'Filodendro (Philodendron spp.) es una especie de la familia Araceae registrada en el inventario de árboles de CUCEI.', NULL, '{}'::text[], NULL, 'perenne', '{}'::int[], NULL, '{"copa":"redonda","hojas":["#3E6A3A","#5C8C49","#8AB463"],"tronco":"#76675A","alto":1,"ancho":1}'::jsonb, NULL, NULL, NULL, NULL, 'Inventario de árboles de CUCEI', 'Persistente', 'Tropical y subtropical húmedo', 'Inflorescencia en espádice, frutos bayas'),
  ('palma-de-betel', 'Palma de betel', ARRAY['Nuez de betel']::text[], 'Areca catechu', 'Arecaceae', 'introducida', NULL, 'Palma de betel (Areca catechu) es una especie de la familia Arecaceae registrada en el inventario de árboles de CUCEI.', NULL, '{}'::text[], NULL, NULL, '{}'::int[], NULL, '{"copa":"palmera","hojas":["#4A6B3E","#6A8D52","#98B677"],"tronco":"#5E4B3D","alto":1.3,"ancho":0.9}'::jsonb, NULL, NULL, NULL, NULL, 'Inventario de árboles de CUCEI', 'Hojas largas, pinnadas, de color verde brillante', 'Tropical, con alta humedad y temperaturas cálidas', 'Inflorescencias pequeñas; fruto en forma de drupa oval, de donde se extrae la nuez de betel (betel nut)'),
  ('hibisco', 'Hibisco', ARRAY['Tulipán']::text[], 'Hibiscus rosa-sinensis', 'Malvaceae', 'introducida', NULL, 'Hibisco (Hibiscus rosa-sinensis) es una especie de la familia Malvaceae registrada en el inventario de árboles de CUCEI.', NULL, '{}'::text[], NULL, 'perenne', '{}'::int[], NULL, '{"copa":"abierta","hojas":["#2F5E35","#4A8044","#78AA5A"],"tronco":"#7C6A58","alto":1,"ancho":1}'::jsonb, NULL, NULL, NULL, NULL, 'Inventario de árboles de CUCEI', 'Perennifolio', 'Tropical, subtropical, cálido', 'Flores grandes y vistosas de varios colores; fruto en cápsula'),
  ('magnolio', 'Magnolio', '{}'::text[], 'Magnolia spp.', 'Magnoliaceae', NULL, NULL, 'Magnolio (Magnolia spp.) es una especie de la familia Magnoliaceae registrada en el inventario de árboles de CUCEI.', NULL, '{}'::text[], NULL, 'caducifolio', '{}'::int[], '#E58DBB', '{"copa":"redonda","hojas":["#3A6439","#58884A","#87B064"],"tronco":"#76675A","flor":"#E58DBB","densidadFlor":0.45,"alto":1,"ancho":1}'::jsonb, NULL, NULL, NULL, NULL, 'Inventario de árboles de CUCEI', 'Deciduo', 'Templado, subtropical', 'Flores grandes, blancas o rosadas en forma de copa; frutos en conos leñosos con semillas rojas'),
  ('cheflera', 'Cheflera', ARRAY['Árbol paraguas']::text[], 'Schefflera actinophylla', 'Araliaceae', 'introducida', NULL, 'Cheflera (Schefflera actinophylla) es una especie de la familia Araliaceae registrada en el inventario de árboles de CUCEI.', NULL, '{}'::text[], NULL, NULL, '{}'::int[], NULL, '{"copa":"redonda","hojas":["#3A6439","#58884A","#87B064"],"tronco":"#6B5444","alto":1,"ancho":1}'::jsonb, NULL, NULL, NULL, NULL, 'Inventario de árboles de CUCEI', 'Hojas compuestas, con 7 a 9 folíolos, de color verde brillante, coriáceas', 'Tropical y subtropical; tolera heladas leves', 'Flores pequeñas y poco vistosas agrupadas en racimos; fruto es una drupa pequeña, de importancia menor en cultivo ornamental'),
  ('arbol-orquidea-de-hong-kong', 'Árbol orquídea de Hong Kong', ARRAY['Bauhinia de Hong Kong', 'Árbol de las orquídeas']::text[], 'Bauhinia blakeana', 'Fabaceae', 'introducida', NULL, 'Árbol orquídea de Hong Kong (Bauhinia blakeana) es una especie de la familia Fabaceae registrada en el inventario de árboles de CUCEI.', NULL, '{}'::text[], NULL, NULL, '{}'::int[], '#8E6CC4', '{"copa":"paraguas","hojas":["#2F5E35","#4A8044","#78AA5A"],"tronco":"#7C6A58","flor":"#8E6CC4","densidadFlor":0.85,"alto":0.95,"ancho":1.25}'::jsonb, NULL, NULL, NULL, NULL, 'Inventario de árboles de CUCEI', 'Hojas simples, bilobuladas, de forma distintiva y de color verde brillante', 'Tropical y subtropical; se adapta a climas cálidos y moderadamente húmedos', 'Flores grandes, vistosas y de forma orquídea (entre 3 y 7 cm de diámetro), de tonos rosados a púrpuras, con aroma delicado; el fruto es una vaina que contiene semillas'),
  ('cipres-de-monterrey', 'Ciprés de Monterrey', '{}'::text[], 'Cupressus macrocarpa', 'Cupressaceae', 'introducida', NULL, 'Ciprés de Monterrey (Cupressus macrocarpa) es una especie de la familia Cupressaceae registrada en el inventario de árboles de CUCEI.', NULL, '{}'::text[], NULL, NULL, '{}'::int[], NULL, '{"copa":"conica","hojas":["#2C5A32","#447A42","#6CA05A"],"tronco":"#5E4B3D","alto":1.2,"ancho":0.85}'::jsonb, NULL, NULL, NULL, NULL, 'Inventario de árboles de CUCEI', 'Hojas en escamas, de color verde azulado, densamente dispuestas en verticilos', 'Mediterráneo; tolera inviernos suaves y veranos cálidos y secos', 'Flores pequeñas y poco vistosas; fruto es una cápsula leñosa que se abre para liberar semillas aladas, aunque su floración es poco notable'),
  ('vid', 'Vid', '{}'::text[], 'Vitis vinifera', 'Vitaceae', 'introducida', NULL, 'Vid (Vitis vinifera) es una especie de la familia Vitaceae registrada en el inventario de árboles de CUCEI.', NULL, '{}'::text[], NULL, NULL, '{}'::int[], NULL, '{"copa":"redonda","hojas":["#3E6A3A","#5C8C49","#8AB463"],"tronco":"#7C6A58","alto":1,"ancho":1}'::jsonb, NULL, NULL, NULL, NULL, 'Inventario de árboles de CUCEI', 'Verde', 'Templado', 'Flores pequeñas, frutos en racimos (uvas)'),
